<?php
// CLI only: php database/create-admin.php "Name" email@example.edu "long test password"
declare(strict_types=1);if(PHP_SAPI!=='cli'||$argc!==4){fwrite(STDERR,"Usage: php database/create-admin.php \"Full Name\" email@example.edu \"password\"\n");exit(1);}require_once dirname(__DIR__).'/config/db.php';require_once dirname(__DIR__).'/repositories/userPDO.php';[$script,$name,$email,$password]=$argv;if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12){fwrite(STDERR,"Use a valid email and a password of at least 12 characters.\n");exit(1);}try{createUser(openDatabase(),trim($name),strtolower(trim($email)),password_hash($password,PASSWORD_DEFAULT),'admin');echo "Administrator account created.\n";}catch(Throwable $e){fwrite(STDERR,"Administrator account was not created.\n");exit(1);}
